def fibonacci(n):
    """Возвращает n‑й член последовательности Фибоначчи."""
    if n < 0:
        return None
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

